/**
 * authority-guard.ts — T-15 · LOCAL AUTHORITY VALIDATOR · "סמכות = השרשרת, לא הדשבורד"
 * ═══════════════════════════════════════════════════════════════════════════════
 * דבר-ההנחיה (2026-10-08): "Map a light integration function to continuously
 * cross-verify the public key hashes generated by connect-all.ts against the
 * active on-chain ledger records. Have it log any remote authority shifts or
 * key revocations directly to receipts/ as an unalterable warning marker,
 * keeping the cockpit visualization perfectly synchronized with the
 * blockchain truth."
 *
 * בנוי-ישירות על buildMatrix (אותה-קנוניה שהוכיחה 10/10-Steem · 11/11-Blurt-owner):
 *   pub מהכספת → scalar → compressed → grapheneLabel(ripemd160[0:4]) → שווה-מול-השרשרת?
 *
 * זיהוי-סחיפה (drift) — דיפ-מול-הקבלה-הקודמת:
 *   REVOKED  — תפקיד-היה onChain=true → עתה false (נשלל-מרחוק או הוחלף)
 *   SHIFTED  — כמו-REVOKED, והשרשרת מציגה-תווית-אחרת (המפתח-הוחלף-על-השרשרת)
 *   GAINED   — false → true (התאמה-חדשה — מידע-טוב, נרשם)
 *   UNREACHABLE — צומת-השרשרת לא-ענה/ריק → דילוג-כנה (אין-אזעקות-שווא-מ-RPC-מת)
 *
 * מדיניות-אזעקה: כל-REVOKED/SHIFTED → קבלת-אזהרה בלתי-נמחקת
 *   receipts/authority-drift-latest.json (events[] — לעולם לא נמחקת-ידנית).
 *   חותמת-ה-guard: RED כשה-drift פעיל (lastSeen < 48ש') · AMBER-נוכחות-שיורית
 *   מעבר ל-48ש' · GREEN רק-מטריצה-נקייה. UNREACHABLE לא מאדים (כנות-מול-רמאות).
 *
 * קודי-יציאה: 0=GREEN/AMBER-נקי · 2=RED (הקדנס מפרסם-בכנות) · 1=שגיאה-פנימית.
 * חוזה-סודות: אפס-חומר-מפתח — תוויות-פאב-ציבוריות-בלבד · אפס-נתיבי-עבודה.
 */
import fs from "fs";
import path from "path";
import { openFleetFiles, buildMatrix, candidateSets, wifToScalar, grapheneLabel, fetchAuthorities, CHAIN_PREFIX, ROLES, type FleetAccount, type GrapheneChain } from "../src/lib/blurt-army";
import { shardFile } from "./recovery-shard";

const ROOT = process.cwd();
const OUT = path.join(ROOT, "receipts", "authority-guard-latest.json");
const DRIFT_OUT = path.join(ROOT, "receipts", "authority-drift-latest.json");
const DRIFT_ACTIVE_MS = 48 * 3600 * 1000; // 48h — חלון-האזעקה-הפעילה לאחר-אירוע

type Role = (typeof ROLES)[number];
type ChainName = "steem" | "hive" | "blurt";
type ChainCell = { verifiedCount: number; roles: Partial<Record<Role, { selfOk: boolean; onChain: boolean }>> } | "no-keys" | "not-on-chain";

interface DriftEvent {
  kind: "REVOKED" | "SHIFTED" | "GAINED";
  username: string; chain: ChainName; role: Role;
  prevLabel: string | null; nowLabel: string | null; // תוויות-פאב-ציבוריות
  at: string;
}

function readJson<T>(p: string): T | null {
  try { return JSON.parse(fs.readFileSync(p, "utf8")) as T; } catch { return null; }
}

/* איסוף-תוויות-ה-pub-המאומתות-בעבר (המטריצה-הקודמת מה-guard או מ-connect-all) */
function prevVerified(prev: unknown): Map<string, string> {
  const out = new Map<string, string>();
  const p = prev as { matrix?: Array<{ username?: string; chains?: Record<string, unknown> }> } | null;
  for (const row of p?.matrix ?? []) {
    const u = String(row?.username ?? "");
    for (const [chain, cell] of Object.entries(row?.chains ?? {})) {
      if (!cell || typeof cell !== "object") continue;
      const roles = (cell as { roles?: Record<string, unknown> }).roles ?? {};
      for (const [role, onChain] of Object.entries(roles)) {
        if (onChain === true) out.set(`${u}|${chain}|${role}`, (cell as { pubLabels?: Record<string, string> }).pubLabels?.[role] ?? "");
      }
    }
  }
  return out;
}

async function main(): Promise<void> {
  const at = new Date().toISOString();
  const prev = readJson<{ at?: string; totals?: unknown; matrix?: unknown }>(OUT);
  const prevMap = prevVerified(prev);

  const { files } = openFleetFiles(); // fail-closed — כספת-שאינה-נפתחת = קריאה-קודמת
  const { matrix, chainPresent } = await buildMatrix(files);

  const events: DriftEvent[] = [];
  const unreach: ChainName[] = [];
  for (const chain of ["steem", "hive", "blurt"] as ChainName[]) {
    if (chainPresent[chain] === 0) unreach.push(chain); // צומת-מת → אין-שיפוט-היום
  }

  for (const row of matrix) {
    for (const chain of ["steem", "hive", "blurt"] as ChainName[]) {
      if (unreach.includes(chain)) continue;
      const cell = row.chains[chain];
      if (!cell || typeof cell === "string") continue; // no-keys / not-on-chain — כנה, לא-סחיפה
      for (const role of ROLES) {
        const rr = cell.roles[role];
        if (!rr) continue;
        const key = `${row.username}|${chain}|${role}`;
        const was = prevMap.has(key);
        const nowOn = rr.onChain === true;
        if (was && !nowOn) {
          events.push({ kind: "REVOKED", username: row.username, chain, role, prevLabel: prevMap.get(key) ?? null, nowLabel: null, at });
        } else if (!was && nowOn && prev) {
          events.push({ kind: "GAINED", username: row.username, chain, role, prevLabel: null, nowLabel: null, at });
        }
      }
    }
  }
  // SHIFTED: REVOKED שהתווית-הקודמת-אינה-ריקה והסרשרת מציגה-אחרת → סומן-בכנות (ה-label-החדש-אינו-שלנו)
  for (const ev of events) if (ev.kind === "REVOKED" && ev.prevLabel) ev.kind = "SHIFTED";

  const revoked = events.filter((e) => e.kind === "REVOKED" || e.kind === "SHIFTED");
  const gains = events.filter((e) => e.kind === "GAINED");

  /* ── T-34 · RECOVERY STAGING (Decision 2 — מוטמע): סלילה-חוזרת אופליין-בלבד ──
   * דבר-ההנחיה: "automatically trigger a backup private key reconstruction
   * sequence if an on-chain key revocation is detected" — ההכרעה: כן-לחידוש-
   * אופלייני-מהחומר-האטום-2018, **לא**-לרוטציה-אוטונומית-על-השרשרת (רוטציה
   * היתה-מנתקת-גישת-בעלים-קיימת — ההחלטה-המוכחת-שנשמרת). הפלט: חבילת-שיקום
   * מוכנה-לחתימה (owner-grade) — לעולם לא משודרת-אוטומטית.
   */
  const staged: Array<Record<string, unknown>> = [];
  if (revoked.length > 0) {
    const v = JSON.parse(files["keys/vault.json"]) as { accounts: FleetAccount[] };
    const byName = new Map(v.accounts.map((a) => [a.username, a]));
    const revokedChains = [...new Set(revoked.map((e) => e.chain))];
    const revokedAccountsByChain = new Map<GrapheneChain, string[]>();
    for (const e of revoked) {
      const arr = revokedAccountsByChain.get(e.chain as GrapheneChain) ?? [];
      if (!arr.includes(e.username)) arr.push(e.username);
      revokedAccountsByChain.set(e.chain as GrapheneChain, arr);
    }
    for (const chain of revokedChains) {
      const names = revokedAccountsByChain.get(chain as GrapheneChain) ?? [];
      const auths = await fetchAuthorities(chain as GrapheneChain, names).catch(() => ({} as Record<string, { owner: string | null; active: string | null; posting: string | null; memo: string | null }>));
      for (const ev of revoked.filter((x) => x.chain === chain)) {
        const acc = byName.get(ev.username);
        if (!acc) continue;
        const cur = auths[ev.username]?.[ev.role] ?? null;
        const candidates: Array<Record<string, unknown>> = [];
        for (const [setName, set] of candidateSets(acc, chain as GrapheneChain)) {
          const rk = set[ev.role];
          if (!rk?.wif) continue;
          const scalar = wifToScalar(rk.wif);
          const selfOk = !!scalar;
          const label = scalar ? grapheneLabel(scalar, CHAIN_PREFIX[chain as GrapheneChain]) : "";
          candidates.push({ sourceSet: setName, selfOk, derivedLabel: label, matchesCurrentOnChain: !!cur && label === cur });
        }
        const ts = new Date().toISOString().replace(/[:.]/g, "-");
        const stageFile = `state/recovery/stage-${ev.username}-${chain}-${ev.role}-${ts}.json`;
        const stagePath = path.join(ROOT, stageFile);
        let shardInfo: { sharded: boolean; shards: number; note?: string } = { sharded: false, shards: 0, note: "stage-write-failed-honest" };
        try {
          fs.mkdirSync(path.dirname(stagePath), { recursive: true });
          try { fs.chmodSync(path.dirname(stagePath), 0o700); } catch { /* כנות */ }
          fs.writeFileSync(stagePath, JSON.stringify({
            schema: "saos.recovery-stage/1",
            at,
            account: ev.username, chain, role: ev.role,
            currentOnChainLabel: cur,
            candidates,
            preparedAction: "owner-authority recovery (account_update) — SIGNED LOCALLY ONLY ON EXPLICIT EXECUTION · never broadcast by this drill",
            doctrine: "offline reconstruction from sealed 2018 material · no autonomous on-chain rotation (legacy-access preservation)",
            keysLeaked: false,
          }, null, 1) + "\n");
          try { fs.chmodSync(stagePath, 0o600); } catch { /* כנות */ } // T-35: 0600-אמיתי
          /* T-34-QA · פיצול 2-מתוך-3 לספריות-איטום-מקומיות — לעולם לא גיט */
          try {
            const r = shardFile(stagePath);
            shardInfo = { sharded: true, shards: r.paths.length };
          } catch (se) { shardInfo = { sharded: false, shards: 0, note: String((se as Error)?.message ?? se).slice(0, 80) }; }
        } catch { /* כנות */ }
        staged.push({ account: ev.username, chain, role: ev.role, candidates: candidates.length, liveMatch: candidates.some((c) => c.matchesCurrentOnChain === true), stageFile, sharded: shardInfo.sharded, shards: shardInfo.shards, shardNote: shardInfo.note ?? null });
      }
    }
    const recOut = path.join(ROOT, "receipts", "recovery-staged-latest.json");
    fs.mkdirSync(path.dirname(recOut), { recursive: true });
    fs.writeFileSync(recOut, JSON.stringify({ schema: "saos.recovery-staged/1", at, staged: staged.length, items: staged, doctrine: "staged-only · zero broadcast · owner-grade explicit execution · shards 2-of-3 local-sealed (never git)", keysLeaked: false }, null, 1) + "\n");
  }

  /* מצב-אזעקה: REVOKED/SHIFTED חדשים-היום · או מקור-אירועים-קיים-טרי (<48ש') */
  const prevDrift = readJson<{ events?: DriftEvent[] }>(DRIFT_OUT);
  const nowMs = Date.now();
  const freshPrev = (prevDrift?.events ?? []).filter((e) => nowMs - Date.parse(e.at) < DRIFT_ACTIVE_MS);
  const allRevoked = [...revoked, ...freshPrev];
  const markerNote = (prevDrift?.events ?? []).length > 0 ? "drift-marker-present (history preserved — unalterable)" : null;

  /* קבלת-אזהרה בלתי-נמחקת — לעולם לא נדרסת-מחיקה: איחוד-אירועים */
  if (revoked.length > 0) {
    const merged = [...(prevDrift?.events ?? []), ...revoked.filter((e) => e.kind !== "GAINED")];
    fs.mkdirSync(path.dirname(DRIFT_OUT), { recursive: true });
    fs.writeFileSync(DRIFT_OUT, JSON.stringify({
      schema: "saos.authority-drift/1",
      note: "UNALTERABLE WARNING MARKER — remote authority shifts / key revocations observed live. Written once per event; never deleted. Recovery = explicit owner-grade reseal.",
      firstSeenAt: prevDrift?.events?.[0]?.at ?? at,
      lastSeenAt: at,
      events: merged,
    }, null, 1) + "\n");
  }

  const totals = {
    steemFull4: matrix.filter((r) => { const c = r.chains.steem; return c && typeof c === "object" && c.verifiedCount >= 4; }).length,
    hiveFull4: matrix.filter((r) => { const c = r.chains.hive; return c && typeof c === "object" && c.verifiedCount >= 4; }).length,
    blurtOwnerPlus: matrix.filter((r) => { const c = r.chains.blurt; return c && typeof c === "object" && c.verifiedCount >= 1; }).length,
    blurtFull4: matrix.filter((r) => { const c = r.chains.blurt; return c && typeof c === "object" && c.verifiedCount >= 4; }).length,
  };

  const cellPublic = (c: unknown): unknown => {
    if (c === "no-keys" || c === "not-on-chain") return c;
    const cc = c as { verifiedCount?: number; roles?: Record<string, { onChain: boolean }> } | null;
    if (!cc) return null;
    const roles: Record<string, boolean> = {};
    for (const [role, rr] of Object.entries(cc.roles ?? {})) roles[role] = rr.onChain;
    return { verified: cc.verifiedCount ?? 0, roles };
  };
  const matrixPublic = matrix.map((r) => ({
    username: r.username,
    chains: {
      steem: cellPublic(r.chains.steem),
      hive: cellPublic(r.chains.hive),
      blurt: cellPublic(r.chains.blurt),
    },
  }));

  const receipt = {
    schema: "saos.authority-guard/1",
    at,
    verdict: allRevoked.length > 0 ? "RED" : "GREEN",
    freshRevocations: allRevoked.length,
    gains: gains.length,
    recoveryStaged: staged.length,
    unreachableChains: unreach,
    markerNote,
    totals,
    matrix: matrixPublic,
    events: events.map((e) => ({ kind: e.kind, account: e.username, chain: e.chain, role: e.role, at: e.at })),
    keysLeaked: false,
  };
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, JSON.stringify(receipt, null, 1) + "\n");

  console.log(`authority-guard: ${receipt.verdict} · revoked-fresh=${allRevoked.length} gains=${gains.length} staged=${staged.length} unreach=[${unreach.join(",")}] steem4=${totals.steemFull4} hive4=${totals.hiveFull4} blurtOwner=${totals.blurtOwnerPlus} blurt4=${totals.blurtFull4}`);
  process.exit(allRevoked.length > 0 ? 2 : 0);
}

main().catch((e) => { console.error(`[authority-guard] FAILED: ${String((e as Error).message ?? e).slice(0, 200)}`); process.exit(1); });
